<template>
  <AppFrame active="duty">
    <view class="xr-content duty-page"><view class="duty-heading"><view><view class="xr-page-title">我的安全履职</view><view class="xr-page-copy">仅展示本人当前真实周期内的履职任务。</view></view><view class="duty-stats"><text class="done">{{ stats.done }} 已完成</text><text class="pending">{{ stats.pending }} 待填写</text></view></view>
      <view class="duty-top-grid"><view class="xr-card completion-card"><view class="card-title-row"><view><view class="xr-section-title">履职完成率</view><view class="xr-caption">当前自然周期</view></view><text>⌃</text></view><view class="completion-body"><view class="completion-ring" :style="{ '--rate': completionRate }"><view><strong>{{ completionRate }}%</strong><text>已完成</text></view></view><view class="completion-info"><text>已分配</text><strong>{{ stats.total }} 项</strong><text>待完成</text><strong>{{ stats.pending }} 项</strong></view></view></view>
        <view class="xr-card priority-card"><view class="priority-label">临期任务</view><view class="priority-title">{{ focusTask ? focusTask.actionName : '当前无临期任务' }}</view><view class="priority-meta">{{ focusTask ? `${focusTask.category} · 截止 ${focusTask.dueDate}` : '所有任务均已处理' }}</view><button v-if="focusTask" class="xr-btn xr-btn-primary" @click="open(focusTask.id)">开始填写</button></view>
        <view class="xr-card upcoming-card"><view class="priority-label blue-label">下一项任务</view><view class="priority-title">{{ upcomingTask ? upcomingTask.actionName : '暂无后续任务' }}</view><view class="priority-meta">{{ upcomingTask ? `周期 ${upcomingTask.periodStart} 至 ${upcomingTask.periodEnd}` : '新周期会按实际日期自动生成' }}</view><view class="upcoming-arrow">→</view></view></view>
      <view class="xr-card registry-card"><view class="registry-heading"><view><view class="xr-section-title">任务台账</view><view class="xr-caption">历史周期只读保留，新周期独立生成。</view></view><view class="registry-filters"><view v-for="item in filters" :key="item.value" class="small-filter" :class="{active:selected===item.value}" @click="selected=item.value;load()">{{ item.label }}</view></view></view><view v-for="task in tasks" :key="task.id" class="duty-row" @click="open(task.id)"><view class="check-box" :class="task.status.toLowerCase()">{{ task.status==='DONE' ? '✓' : '' }}</view><view class="duty-body"><view class="duty-name">{{ task.actionName }}</view><view class="duty-meta">{{ task.category }} · {{ frequencyText(task.frequency) }} · 截止 {{ task.dueDate }}</view></view><view class="xr-status" :class="statusClass(task.status)">{{ dutyStatusText(task.status) }}</view><text class="row-more">⋮</text></view><view v-if="!tasks.length" class="xr-empty">当前筛选没有履职任务</view><view class="history-link">查看全部履职历史⌄</view></view></view>
  </AppFrame>
</template>
<script setup>
import { computed, onMounted, ref } from 'vue'
import AppFrame from '../../components/AppFrame.vue'
import { dutyStatusText, listMyDuties } from '../../services/duty'
const tasks=ref([]),selected=ref('')
const filters=[{label:'全部任务',value:''},{label:'待填写',value:'PENDING'},{label:'已完成',value:'DONE'}]
const stats=computed(()=>({total:tasks.value.length,done:tasks.value.filter((item)=>item.status==='DONE').length,pending:tasks.value.filter((item)=>item.status==='PENDING'||item.status==='OVERDUE').length}))
const completionRate=computed(()=>stats.value.total?Math.round(stats.value.done/stats.value.total*100):0)
const focusTask=computed(()=>tasks.value.find((item)=>item.status==='OVERDUE')||tasks.value.find((item)=>item.status==='PENDING'))
const upcomingTask=computed(()=>tasks.value.find((item)=>item.status==='PENDING'&&item.id!==focusTask.value?.id))
async function load(){tasks.value=await listMyDuties({status:selected.value})}function open(id){uni.navigateTo({url:`/pages/duty/record?id=${id}`})}function frequencyText(value){return ({weekly:'每周',biweekly:'每两周',monthly:'每月',quarterly:'每季度',semiannual:'每半年',annual:'每年'})[value]||value}function statusClass(status){return ({PENDING:'xr-status-warning',OVERDUE:'xr-status-major',DONE:'xr-status-review'})[status]||'xr-status-muted'}onMounted(load)
</script>
<style lang="scss" scoped>
