c90;font-size:30rpx}.registry-card{margin-top:16rpx}.registry-filters{display:flex;gap:6rpx;flex-wrap:wrap;justify-content:flex-end}.small-filter{padding:6rpx 9rpx;border-radius:99rpx;background:#f3f5f7;color:#7a8592;font-size:17rpx}.small-filter.active{background:#003c90;color:#fff}.duty-row{display:flex;align-items:center;gap:12rpx;padding:15rpx 0;border-top:1rpx solid #edf0f3}.check-box{width:28rpx;height:28rpx;flex:0 0 28rpx;display:flex;align-items:center;justify-content:center;border:1rpx solid #ccd4de;border-radius:5rpx;color:#fff;font-size:18rpx}.check-box.done{background:#003c90;border-color:#003c90}.check-box.overdue{border-color:#ef4444;background:#fff0ef}.duty-body{min-width:0;flex:1}.duty-name{color:#36414f;font-size:21rpx;font-weight:680}.duty-meta{margin-top:4rpx;color:#85909c;font-size:17rpx;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.row-more{padding-left:5rpx;color:#87919c;font-size:26rpx}.history-link{margin-top:12rpx;color:#003c90;font-size:19rpx;text-align:center}@media(min-width:900px){.duty-heading{margin:0 0 16px}.duty-stats{gap:6px}.duty-stats text{padding:5px 8px;font-size:9px}.duty-top-grid{grid-template-columns:1.05fr 1fr 1fr;gap:12px}.completion-card,.priority-card,.upcoming-card,.registry-card{padding:16px}.completion-body{gap:18px;margin-top:14px}.completion-ring{width:102px;height:102px}.completion-ring::after{inset:9px}.completion-ring strong{font-size:23px}.completion-ring text{font-size:9px}.completion-info{gap:6px 10px}.completion-info text{font-size:9px}.completion-info strong{font-size:11px}.priority-label{padding:4px 7px;font-size:9px}.priority-title{margin-top:11px;font-size:15px}.priority-meta{margin-top:5px;font-size:10px}.priority-card .xr-btn{margin-top:13px}.upcoming-arrow{right:16px;bottom:13px;font-size:22px}.registry-card{margin-top:14px}.small-filter{padding:4px 7px;font-size:9px}.duty-row{gap:10px;padding:11px 0}.check-box{width:18px;height:18px;flex-basis:18px;border-radius:4px;font-size:11px}.duty-na